def parse_price(s: str) -> float | None:
    if s is None:
        return None

    text = str(s).replace("\xa0", " ").strip()
    if not text:
        return None

    lowered = text.casefold()
    if "gratis" in lowered:
        return 0.0

    cleaned = "".join(ch for ch in text if ch.isdigit() or ch in ",.-")
    if not any(ch.isdigit() for ch in cleaned):
        return None

    sign = 1
    first_digit = next((i for i, ch in enumerate(cleaned) if ch.isdigit()), -1)
    if first_digit > 0 and "-" in cleaned[:first_digit]:
        sign = -1

    cleaned = cleaned.replace("-", "").strip(".,")
    if not cleaned or not any(ch.isdigit() for ch in cleaned):
        return None

    if "," in cleaned and "." in cleaned:
        if cleaned.rfind(",") > cleaned.rfind("."):
            cleaned = cleaned.replace(".", "").replace(",", ".")
        else:
            cleaned = cleaned.replace(",", "")
    elif "," in cleaned:
        cleaned = cleaned.replace(",", "", cleaned.count(",") - 1).replace(",", ".")
    elif "." in cleaned:
        dot_pos = cleaned.rfind(".")
        before = cleaned[:dot_pos]
        after = cleaned[dot_pos + 1:]

        if cleaned.count(".") == 1 and len(after) == 3 and before.isdigit():
            cleaned = before + after
        else:
            cleaned = cleaned.replace(".", "", cleaned.count(".") - 1)

    try:
        return sign * float(cleaned)
    except ValueError:
        return None

import re

_POSTCODE_RE = re.compile(r"[1-9]\d{3} ?[A-Za-z]{2}")

def is_valid_postcode(s: str) -> bool:
    if not isinstance(s, str) or not _POSTCODE_RE.fullmatch(s):
        return False

    letters = s[-2:].upper()
    return letters not in {"SA", "SD", "SS"}

def dedupe(listings: list[dict]) -> list[dict]:
    def normalize_title(title: str) -> str:
        return " ".join(str(title).lower().split())

    best_index: dict[tuple[str, int], int] = {}
    best_date: dict[tuple[str, int], str] = {}

    for i, listing in enumerate(listings):
        key = (normalize_title(listing["title"]), listing["price"])
        date = listing["date"]

        if key not in best_date or date < best_date[key]:
            best_date[key] = date
            best_index[key] = i

    keep = set(best_index.values())
    return [listing for i, listing in enumerate(listings) if i in keep]

def add_tag(tag, tags=[]):
    # add tag once, return a NEW sorted list; tags is not modified
    if tag in tags:
        return sorted(tags)
    return sorted(list(tags) + [tag])

import csv
import io


def totals_by_payment(csv_text: str) -> dict[str, int]:
    totals: dict[str, int] = {}
    reader = csv.DictReader(io.StringIO(csv_text.lstrip("\ufeff")))

    for row in reader:
        payment = (row.get("payment") or "").strip().lower()
        if not payment:
            continue

        price = (row.get("price") or "").strip().replace(",", "")
        if not price:
            continue

        try:
            amount = int(price)
        except ValueError:
            continue

        totals[payment] = totals.get(payment, 0) + amount

    return totals

import time


def retry(fn, attempts=3, exceptions=(Exception,), sleep=time.sleep, base_delay=1.0):
    for attempt in range(attempts):
        try:
            return fn()
        except exceptions:
            if attempt == attempts - 1:
                raise
            sleep(base_delay * (2 ** attempt))

    return None

import json

def extract_json(text: str):
    if not isinstance(text, str):
        return None

    decoder = json.JSONDecoder()
    start = 0

    while True:
        start = text.find("{", start)
        if start == -1:
            return None

        try:
            value, _ = decoder.raw_decode(text, start)
        except (json.JSONDecodeError, ValueError):
            start += 1
            continue

        if isinstance(value, dict):
            return value

        start += 1
